/// What the customer's standing with the office is worth, as a single share of
/// the policy base premium. Every quote carries the initial assessment
/// surcharge; a long-standing customer earns the loyalty discount against it.
/// This is the office's customer-history policy, and the rest of the premium
/// calculation does not need to know which clauses it is made of.
fn policy_modifier_rate_of(customer: &Customer) -> f64 {
    let mut modifier_rate = FIRST_INSURANCE_SURCHARGE;
    if customer.years_with_mhpco >= LOYALTY_YEARS {
        modifier_rate -= LOYALTY_DISCOUNT;
    }
    modifier_rate
}

/// Policy-wide modifiers apply to the policy base premium, the sum of all item
/// base premiums, at the single rate the customer's standing earns.
fn with_policy_modifiers(customer: &Customer, policy_base_premium: f64) -> f64 {
    policy_base_premium + policy_base_premium * policy_modifier_rate_of(customer)
/// The single customer a scenario's policies belong to.
pub struct Customer {
    pub years_with_mhpco: i64,
}

/// The premium in G the office charges this customer for insuring these items.
pub fn quote(customer: &Customer, items: &[Item]) -> Result<i64, String> {
